const guard = self.parent
at_first: bool = true
fn next_point() {
    if at_first {
        at_first = false
        guard.navigate_to([12, 0, 6], 2.0, 0.3)
    } else {
        at_first = true
        guard.navigate_to([6, 0, 12], 2.0, 0.3)
    }
}
guard.on_navigation_finished = fn() {
    next_point()
}
guard.on_navigation_failed = fn(reason) {
    debug.log("Path unavailable:", reason)
}
next_point()

const actor = self.parent
good_points: basket = []
bad_points: basket = []
goal: basket = [5, 0, 8]
actor.on_navigation_finished = fn() {
    good_points.insert(good_points.len(), goal)
}
actor.on_navigation_failed = fn(reason) {
    bad_points.insert(bad_points.len(), goal)
    debug.log(reason)
}
actor.navigate_to(goal, 2.0, 0.25)

const actor = self.parent
if actor.is_navigating() {
    actor.cancel_navigation()
}

